import{_ as t,o as a,c as o,a3 as n}from"./chunks/framework.D1iekJsc.js";const m=JSON.parse('{"title":"Configure in MiniTavern","description":"Connect MiniTavern to Ollama, LM Studio, KoboldCPP, llama.cpp — Settings → Model link, OpenAI-compatible Base URL and Test.","frontmatter":{"title":"Configure in MiniTavern","description":"Connect MiniTavern to Ollama, LM Studio, KoboldCPP, llama.cpp — Settings → Model link, OpenAI-compatible Base URL and Test.","head":[["meta",{"name":"keywords","content":"tavern,AI tavern,MiniTavern,AI companion,AI friend,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobile,Silly Tavern Android,Silly Tavern iOS,AI roleplay,character card,AI chat,mobile AI,offline AI,AI story,local LLM,Ollama,LM Studio,lorebook,regex,BYOK,user guide,docs,AI chat client"}],["meta",{"property":"og:title","content":"Configure in MiniTavern · MiniTavern Docs"}],["meta",{"property":"og:description","content":"Connect MiniTavern to Ollama, LM Studio, KoboldCPP, llama.cpp — Settings → Model link, OpenAI-compatible Base URL and Test."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/en/connect-app/minitavern"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/en/connect-app/minitavern"}]]},"headers":[],"relativePath":"en/connect-app/minitavern.md","filePath":"en/connect-app/minitavern.md","lastUpdated":1787224147000}'),l={name:"en/connect-app/minitavern.md"};function r(i,e,d,s,c,p){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="configure-in-minitavern" tabindex="-1">Configure in MiniTavern <a class="header-anchor" href="#configure-in-minitavern" aria-label="Permalink to &quot;Configure in MiniTavern&quot;">​</a></h1><p>App path: <strong>Settings → Models → Model link</strong>.</p><h2 id="create-a-link" tabindex="-1">Create a link <a class="header-anchor" href="#create-a-link" aria-label="Permalink to &quot;Create a link&quot;">​</a></h2><ol><li>Open MiniTavern → bottom <strong>Settings</strong>.</li><li><strong>Models</strong> → <strong>Model link</strong>.</li><li>Tap <strong>New</strong> (top-right).</li><li><strong>Model platform</strong>: <strong>Custom</strong> (OpenAI-compatible / custom Base URL — exact label follows the current App).</li><li>Fill the table for your tool, save; if <strong>Test</strong> is available, Test before setting as default.</li></ol><h2 id="examples-by-tool" tabindex="-1">Examples by tool <a class="header-anchor" href="#examples-by-tool" aria-label="Permalink to &quot;Examples by tool&quot;">​</a></h2><p>Replace <code>YOUR_PC_IP</code> with the PC LAN IP (never <code>localhost</code>).</p><table tabindex="0"><thead><tr><th>Tool</th><th>Base URL example</th><th>Model name</th><th>API Key</th></tr></thead><tbody><tr><td><a href="/ultra_guides/en/ollama/lan">Ollama</a></td><td><code>http://YOUR_PC_IP:11434/v1</code></td><td>Name from <code>ollama list</code></td><td>Empty or <code>ollama</code></td></tr><tr><td><a href="/ultra_guides/en/lmstudio/server">LM Studio</a></td><td><code>http://YOUR_PC_IP:1234/v1</code></td><td>id from Local Server</td><td>Empty</td></tr><tr><td><a href="/ultra_guides/en/koboldcpp/server">KoboldCPP</a></td><td><code>http://YOUR_PC_IP:5001/v1</code></td><td>id from <code>/v1/models</code></td><td>Empty</td></tr><tr><td><a href="/ultra_guides/en/llamacpp/server">llama.cpp</a></td><td><code>http://YOUR_PC_IP:8080/v1</code></td><td>id from server</td><td>Empty</td></tr><tr><td><a href="/ultra_guides/en/localai/install">LocalAI</a></td><td><code>http://YOUR_PC_IP:8080/v1</code></td><td>LocalAI config name</td><td>Per auth settings</td></tr><tr><td><a href="/ultra_guides/en/jan/install">Jan</a></td><td>Address on the app API page</td><td>id from the list</td><td>Per app settings</td></tr><tr><td><a href="/ultra_guides/en/textgen/install">text-generation-webui</a></td><td><code>http://YOUR_PC_IP:port/v1</code></td><td>id from the extension</td><td>Per extension settings</td></tr></tbody></table><p>Aliases are up to you, e.g. <code>Home Ollama</code>, <code>Office Kobold</code>.</p><h2 id="set-default-and-chat" tabindex="-1">Set default and chat <a class="header-anchor" href="#set-default-and-chat" aria-label="Permalink to &quot;Set default and chat&quot;">​</a></h2><ol><li>In the model link list, set as <strong>Default</strong>.</li><li>Import or pick a character card and send a message.</li><li>The PC tool should show request activity; the App should stream or show a full reply.</li></ol><h2 id="per-chat-override-optional" tabindex="-1">Per-chat override (optional) <a class="header-anchor" href="#per-chat-override-optional" aria-label="Permalink to &quot;Per-chat override (optional)&quot;">​</a></h2><p>To temporarily use another local model for one chat: override the global default model link / parameters in chat settings.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><strong>Do not</strong> put <code>http://localhost:...</code> or <code>http://127.0.0.1:...</code> on the phone.</li><li>Prefer a Base URL ending in <code>/v1</code>, not <code>/chat/completions</code>.</li><li>PC sleep, lid close, or network changes can change the IP.</li><li>Ports are whatever you actually opened; the table is common defaults only.</li></ul><p>Cannot connect? <a href="/ultra_guides/en/troubleshoot">Troubleshoot</a>. Pick a tool: <a href="/ultra_guides/en/local/tools">Tools overview</a>.</p>',15)])])}const u=t(l,[["render",r]]);export{m as __pageData,u as default};
